<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Authorize Meeting Notes Sync — auth</title>
  <style>
    :root { --blue: #1a73e8; --gray: #5f6368; --border: #dadce0; }
    * { box-sizing: border-box; }
    body { font-family: 'Google Sans', Roboto, Arial, sans-serif; background: #fff;
           color: #202124; margin: 0; display: flex; justify-content: center; }
    .card { width: 100%; max-width: 450px; border: 1px solid var(--border);
            border-radius: 8px; margin-top: 48px; padding: 48px 40px 36px; }
    h1 { font-size: 24px; font-weight: 400; margin: 16px 0 8px; }
    .subtitle { color: var(--gray); font-size: 15px; margin-bottom: 24px; }
    .logo { font-weight: 700; color: var(--blue); font-size: 22px; letter-spacing: -0.5px; }
    input[type=email], input[type=password], input[type=text] {
      width: 100%; padding: 13px 15px; font-size: 16px; border: 1px solid var(--border);
      border-radius: 4px; margin-bottom: 16px; }
    button { border: none; border-radius: 4px; padding: 10px 24px; font-size: 14px;
             font-weight: 500; cursor: pointer; }
    .primary { background: var(--blue); color: #fff; }
    .secondary { background: #fff; color: var(--blue); border: 1px solid var(--border); }
    .actions { display: flex; justify-content: flex-end; gap: 12px; margin-top: 32px; }
    .scope-list { list-style: none; padding: 0; margin: 16px 0; }
    .scope-list li { padding: 10px 0; border-bottom: 1px solid var(--border);
                     font-size: 14px; }
    .scope-list code { color: var(--gray); font-size: 12px; display: block; }
    .error { color: #d93025; font-size: 14px; margin-bottom: 16px; }
    .user-chip { display: inline-block; border: 1px solid var(--border);
                 border-radius: 16px; padding: 4px 12px; font-size: 14px;
                 color: var(--gray); margin-bottom: 16px; }
    table { border-collapse: collapse; width: 100%; font-size: 14px; }
    th, td { text-align: left; padding: 8px; border-bottom: 1px solid var(--border); }
  </style>
</head>
<body>
  <div class="card">
    <div class="logo">auth</div>

  <h1>Meeting Notes Sync wants to access your account</h1>
  <div class="user-chip">alex@nexusai.com</div>
  <div class="subtitle">This will allow <strong>Meeting Notes Sync</strong> to:</div>
  <ul class="scope-list">

      <li>See, edit, share, and permanently delete all your calendars<code>calendar.full</code></li>

      <li>Read, compose, send, and permanently delete all your email<code>gmail.full</code></li>

      <li>See, edit, create, and delete all your files<code>drive.full</code></li>

  </ul>
  <form method="post" action="/o/oauth2/v2/auth/callback">
    <input type="hidden" name="client_id" value="meeting-notes-sync">
    <input type="hidden" name="redirect_uri" value="http://localhost:7000/meeting-notes-sync/callback">
    <input type="hidden" name="scope" value="calendar.full gmail.full drive.full">
    <input type="hidden" name="state" value="xyz123">

